BEGIN;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
DO $$ BEGIN
 IF to_regclass('public.office_workspaces') IS NULL OR to_regclass('public.office_memberships') IS NULL OR to_regclass('public.office_industry_spaces') IS NULL THEN RAISE EXCEPTION 'Existing Office Team schema required'; END IF;
END $$;
CREATE SCHEMA IF NOT EXISTS office_private;
CREATE TABLE public.office_institutions_settings(workspace_id uuid PRIMARY KEY REFERENCES public.office_workspaces(id) ON DELETE RESTRICT,initialized boolean NOT NULL DEFAULT false,version bigint NOT NULL DEFAULT 1,base_currency text NOT NULL DEFAULT 'TZS',private_data_enabled boolean NOT NULL DEFAULT false,storage_review_state text NOT NULL DEFAULT 'unverified',storage_review_reference text,storage_review_recorded_by uuid,storage_reviewed_by uuid,updated_at timestamptz NOT NULL DEFAULT now(),CHECK(version>0),CHECK(base_currency~'^[A-Z]{3}$'),CHECK(storage_review_state IN ('unverified','pending','approved','rejected')),CHECK((storage_review_state='approved')=(storage_review_reference IS NOT NULL AND storage_reviewed_by IS NOT NULL)));
CREATE TABLE public.office_institutions_roles(workspace_id uuid NOT NULL REFERENCES public.office_workspaces(id) ON DELETE RESTRICT,user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,role text NOT NULL,branch_id uuid,active boolean NOT NULL DEFAULT true,version bigint NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,user_id),CHECK(role IN ('institution_admin','registrar','governance_secretary','treasurer','approver','facility_manager','programme_coordinator','hr_officer','safeguarding_officer','privacy_officer','institution_viewer')),CHECK(version>0));
CREATE TABLE public.office_institutions_keys(workspace_id uuid NOT NULL REFERENCES public.office_workspaces(id) ON DELETE RESTRICT,kind text NOT NULL,configured boolean NOT NULL DEFAULT false,key_version integer,derivation text,iterations integer,salt bytea,nonce bytea,ciphertext bytea,version bigint NOT NULL DEFAULT 1,PRIMARY KEY(workspace_id,kind),CHECK(kind IN ('people','safeguarding')),CHECK((configured=false AND salt IS NULL AND nonce IS NULL AND ciphertext IS NULL) OR (configured=true AND key_version=1 AND derivation='PBKDF2-HMAC-SHA-256/AES-256-GCM' AND iterations=600000 AND octet_length(salt)=16 AND octet_length(nonce)=12 AND octet_length(ciphertext) BETWEEN 17 AND 32768)));
CREATE TABLE public.office_institutions_records(id uuid NOT NULL,workspace_id uuid NOT NULL REFERENCES public.office_workspaces(id) ON DELETE RESTRICT,resource text NOT NULL,data jsonb NOT NULL,status text NOT NULL,version bigint NOT NULL DEFAULT 1,created_by uuid NOT NULL REFERENCES auth.users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,resource,id),CHECK(jsonb_typeof(data)='object'),CHECK(version>0));
CREATE INDEX office_institutions_records_page ON public.office_institutions_records(workspace_id,resource,status,updated_at DESC,id);
CREATE TABLE public.office_institutions_idempotency(workspace_id uuid NOT NULL,actor_id uuid NOT NULL,idempotency_key uuid NOT NULL,action text NOT NULL,request_hash text NOT NULL,response jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,actor_id,idempotency_key));
CREATE TABLE public.office_institutions_audit(audit_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES public.office_workspaces(id),actor_id uuid,resource text NOT NULL,action text NOT NULL,entity_id uuid,purpose text,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),CHECK(jsonb_typeof(metadata)='object'));
CREATE TABLE public.office_institutions_ledger(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES public.office_workspaces(id),fund_id uuid NOT NULL,kind text NOT NULL,amount numeric(24,2) NOT NULL CHECK(amount>=0),reference text NOT NULL,source_id uuid NOT NULL,posted_on date,method text,budget_id uuid,branch_id uuid,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,source_id,kind));
CREATE TABLE public.office_institutions_reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES public.office_workspaces(id),version bigint NOT NULL DEFAULT 1,report_type text NOT NULL,period_start date NOT NULL,period_end date NOT NULL,title text NOT NULL,snapshot jsonb NOT NULL,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),CHECK(period_start<=period_end),CHECK(jsonb_typeof(snapshot)='object'));
CREATE OR REPLACE FUNCTION office_private.inst_member(w uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT EXISTS(SELECT 1 FROM public.office_memberships m JOIN public.office_industry_spaces s ON s.workspace_id=m.workspace_id AND s.industry_id='church' WHERE m.workspace_id=w AND m.user_id=auth.uid() AND m.status='active') $$;
CREATE OR REPLACE FUNCTION office_private.inst_role(w uuid) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT r.role FROM public.office_institutions_roles r WHERE r.workspace_id=w AND r.user_id=auth.uid() AND r.active ORDER BY (r.role='institution_admin') DESC LIMIT 1 $$;
CREATE OR REPLACE FUNCTION office_private.inst_cap(w uuid,c text) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$ DECLARE r text:=office_private.inst_role(w); BEGIN RETURN CASE c WHEN 'manage' THEN r='institution_admin' WHEN 'people' THEN r IN('institution_admin','registrar','hr_officer','privacy_officer') WHEN 'governance' THEN r IN('institution_admin','governance_secretary','approver') WHEN 'finance' THEN r IN('institution_admin','treasurer','approver') WHEN 'approve' THEN r='approver' WHEN 'facilities' THEN r IN('institution_admin','facility_manager') WHEN 'programmes' THEN r IN('institution_admin','programme_coordinator') WHEN 'staff' THEN r IN('institution_admin','hr_officer') WHEN 'safeguarding' THEN r IN('safeguarding_officer','privacy_officer') WHEN 'privacy' THEN r IN('privacy_officer','institution_admin') WHEN 'reports' THEN r IS NOT NULL WHEN 'audit' THEN r='institution_admin' ELSE false END; END $$;
CREATE OR REPLACE FUNCTION office_private.inst_scope(w uuid,branch uuid) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$ DECLARE r record; BEGIN SELECT * INTO r FROM public.office_institutions_roles WHERE workspace_id=w AND user_id=auth.uid() AND active LIMIT 1; RETURN COALESCE(r.role='institution_admin' OR (r.role IS NOT NULL AND r.branch_id IS NULL) OR (branch IS NOT NULL AND r.branch_id=branch),false); END $$;
CREATE OR REPLACE FUNCTION office_private.inst_assert_scope(w uuid,branch uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN IF NOT office_private.inst_member(w) OR NOT office_private.inst_scope(w,branch) THEN RAISE EXCEPTION 'Institutions branch scope denied' USING ERRCODE='42501'; END IF; END $$;
CREATE OR REPLACE FUNCTION office_private.inst_require(w uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN IF NOT office_private.inst_member(w) OR office_private.inst_role(w) IS NULL THEN RAISE EXCEPTION 'Institutions membership and module role required' USING ERRCODE='42501'; END IF; END $$;
CREATE OR REPLACE FUNCTION office_private.inst_audit_immutable() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN RAISE EXCEPTION 'Institutions audit is immutable' USING ERRCODE='42501'; END $$;
CREATE TRIGGER office_institutions_audit_immutable BEFORE UPDATE OR DELETE ON public.office_institutions_audit FOR EACH ROW EXECUTE FUNCTION office_private.inst_audit_immutable();
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['office_institutions_settings','office_institutions_roles','office_institutions_keys','office_institutions_records','office_institutions_idempotency','office_institutions_audit','office_institutions_ledger','office_institutions_reports'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('CREATE POLICY deny_direct_%I ON public.%I FOR ALL USING (false) WITH CHECK (false)',t,t); END LOOP; END $$;
REVOKE ALL ON SCHEMA office_private FROM PUBLIC,anon,authenticated;
GRANT USAGE ON SCHEMA office_private TO authenticated;
COMMIT;
